test('progressive delivery help stays static and concise while exact actions disclose fields and authority',()=>{const never=new Proxy({},{get(){throw new Error('Help must not touch runtime services')}}),delivery=new DeliveryService({ctx:never,store:never}),catalog=delivery.help(),actions=catalog.actions;assert.equal(actions.length,23);assert.equal(new Set(actions.map(row=>row.action)).size,23);for(const row of actions)assert.deepEqual(Object.keys(row).sort(),['action','description']);const details=actions.map(row=>delivery.help(row.action));assert.ok(JSON.stringify(catalog).length<JSON.stringify(details).length/2,'global discovery must defer detailed DTOs');assert.equal(delivery.help('git.commit').userOnly,true);assert.match(delivery.help('git.commit').fields.paths,/required/);assert.equal(delivery.help('git.status').userOnly,false);assert.equal(delivery.help('source.start').fields.expectedRevision,undefined);assert.match(delivery.help('source.logs').fields.stdoutOffset,/nextOffset/);assert.match(delivery.help('source.map').fields.line,/1-based/);assert.match(delivery.help('export.create').fields.format,/design-package/);assert.ok(delivery.help('export.create').fields.expectedPageRevisions);assert.match(delivery.help('share.create').fields.scope,/required owner/);assert.match(delivery.help('share.update').fields.expectedShareRevision,/required/);const changed=delivery.help('share.create');changed.fields.scope='tampered';assert.notEqual(delivery.help('share.create').fields.scope,'tampered');assert.throws(()=>delivery.help('toString'),{code:'UNKNOWN_ACTION'});assert.equal(delivery.runs.size,0);});
const contained=(root,p)=>{const rel=path.relative(root,p);return rel===''||rel!=='..'&&!rel.startsWith('..'+path.sep)&&!path.isAbsolute(rel)};
const checked=(root,p)=>{assert.ok(path.isAbsolute(p)&&contained(root,p));return p};
async function canonical(p){try{return await fs.realpath(p)}catch(error){if(error.code!=='ENOENT')throw error;return path.join(await canonical(path.dirname(p)),path.basename(p))}}
class NativeFS {
  constructor(root){this.root=root;this.writes=[];}
  absolute(target){return checked(this.root,target.displayPath)}
  async resolve(value,{cwd=this.root,signal}={}){signal?.throwIfAborted();const absolute=checked(this.root,await canonical(checked(this.root,path.resolve(cwd,value))));return {displayPath:absolute,targetKey:`opaque:${absolute}`}}
  processPath(target){return this.absolute(target)}
  contains(a,b){return contained(this.absolute(a),this.absolute(b))}
  async stat(target,signal){signal?.throwIfAborted();try{const p=this.absolute(target),s=await fs.stat(p,{bigint:true}),type=s.isFile()?'file':s.isDirectory()?'directory':'other';return {type,size:Number(s.size),version:`${s.ino}:${s.mtimeNs}:${s.size}:${type==='file'?sha(await fs.readFile(p)):''}`}}catch(error){if(error.code==='ENOENT')return undefined;throw error}}
  async readText(target,signal){signal?.throwIfAborted();return new TextDecoder('utf-8',{fatal:true}).decode(await fs.readFile(this.absolute(target)))}
  async readBytes(target,signal,maxBytes){const info=await this.stat(target,signal);if(!info||info.size>maxBytes)throw Object.assign(Error('Bounded test read refused'),{code:'FS_TOO_LARGE'});const bytes=await fs.readFile(this.absolute(target));assert.ok(bytes.length<=maxBytes);return bytes}
  async writeText(target,content,expected,signal,policy){signal?.throwIfAborted();const p=this.absolute(target);if(policy.mode==='read-only'||policy.mode==='workspace-write'&&!contained(policy.workspaceRoot,p))throw Object.assign(Error('Denied'),{code:'FS_SANDBOX_DENIED'});const before=await this.stat(target),old=before?await this.readText(target):null;if(expected?.kind==='createIfAbsent'&&before)throw Object.assign(Error('Exists'),{code:'FS_ALREADY_EXISTS'});if(expected?.kind==='replaceIfVersion'&&expected.version!==before?.version)throw Object.assign(Error('Stale'),{code:'FS_STALE_VERSION'});await fs.mkdir(checked(this.root,path.dirname(p)),{recursive:true});const staged=checked(this.root,`${p}.stage-${randomUUID()}`);await fs.writeFile(staged,content,{flag:'wx'});try{if(expected?.kind==='createIfAbsent')await fs.link(checked(this.root,staged),checked(this.root,p));else await fs.rename(checked(this.root,staged),checked(this.root,p));}finally{assert.ok(path.basename(staged).startsWith(path.basename(p)+'.stage-'));await fs.unlink(checked(this.root,staged)).catch(error=>{if(error.code!=='ENOENT')throw error})}this.writes.push({path:p,policy,expected});return {version:(await this.stat(target)).version,operation:before?'update':'create',before:old,after:content}}
}
function nativeShell(root){const requests=[],executions=[];return {requests,executions,resolve(request){checked(root,request.workdir);requests.push(request);return {timeoutMs:30000,onExpiry:'kill',stdoutMaxBytes:2_000_000,...request}},async execute(spec){spec.signal?.throwIfAborted();const child=spawn('bash',['-c',spec.command],{cwd:checked(root,spec.workdir),stdio:['pipe','pipe','pipe']}),events=new EventEmitter();let stdout=Buffer.alloc(0),stderr=Buffer.alloc(0),aborted=false,timedOut=false,resolveDone;const done=new Promise(resolve=>{resolveDone=resolve});const output=(buffer,offset)=>({text:buffer.subarray(offset).toString('utf8'),nextOffset:buffer.length,lossy:false});const handle={child,events,done,status:'running',exitCode:null,observed:{stdout:{readFrom:offset=>output(stdout,offset)},stderr:{readFrom:offset=>output(stderr,offset)}},kill(){return child.kill('SIGKILL')}};const result=new Promise((resolve,reject)=>{const abort=()=>{aborted=true;child.kill('SIGKILL')};spec.signal?.addEventListener('abort',abort,{once:true});const timer=spec.onExpiry==='kill'?setTimeout(()=>{timedOut=true;child.kill('SIGKILL')},spec.timeoutMs):null;child.stdout.on('data',bytes=>{stdout=Buffer.concat([stdout,bytes]);events.emit('stdout')});child.stderr.on('data',bytes=>{stderr=Buffer.concat([stderr,bytes]);events.emit('stderr')});child.once('error',reject);child.once('close',(exitCode,signal)=>{if(timer)clearTimeout(timer);spec.signal?.removeEventListener('abort',abort);handle.status='completed';handle.exitCode=exitCode;resolveDone();resolve({exitCode,signal,aborted,timedOut,timeoutMs:spec.timeoutMs,stdout:{text:stdout.toString('utf8'),truncated:stdout.length>spec.stdoutMaxBytes},stderr:{text:stderr.toString('utf8'),truncated:stderr.length>spec.stdoutMaxBytes}})});child.stdin.on('error',error=>{if(error.code!=='EPIPE')reject(error)});child.stdin.end(spec.stdin)});handle.result=()=>result;executions.push(handle);return handle}}}
function runGit(directory,...args){const value=spawnSync('git',args,{cwd:directory,encoding:'utf8',env:{...process.env,GIT_TERMINAL_PROMPT:'0'}});assert.equal(value.status,0,value.stderr);return value.stdout.trim()}
async function fixture(work){const workspace=await fs.realpath(process.cwd()),name=`.delivery-test-${randomUUID()}`,selected=path.resolve(workspace,name);assert.equal(path.dirname(selected),workspace);await fs.mkdir(selected,{mode:0o700});const root=await fs.realpath(selected);assert.equal(root,selected);const provider=new NativeFS(root),policy={mode:'workspace-write',workspaceRoot:root,sessionId:'test-owner'},shell=nativeShell(root),store=new DesignerStore({fs:provider,workspaceRoot:root,root:"Library ' $()",policy:()=>policy});const owner={store,ctx:{fs:provider,shell,webServer:{getOrigin:()=> 'http://127.0.0.1:53998'},connection:{admit:req=>req.headers?.authorization==='owner'?{peer:{principal:{kind:'owner'}}}:{rejection:401}}},workbench:{hasUnsavedDrafts:async()=>({dirty:false,resources:[]})},documentExport:html=>({html:html.replace('</body>','<script data-dsh-runtime="1">globalThis.deliveryInteraction = true;</script></body>'),diagnostics:[]})},service=new DeliveryService(owner);try{return await work({root,provider,policy,shell,store,owner,service,context:{policy,user:true}})}finally{await service.dispose();const actual=await fs.realpath(selected);assert.equal(actual,root);assert.equal(actual,path.resolve(workspace,name));assert.equal(path.dirname(actual),workspace);assert.match(path.basename(actual),/^\.delivery-test-[a-f0-9-]{36}$/);assert.equal((await fs.lstat(actual)).isSymbolicLink(),false);await fs.rm(actual,{recursive:true,force:true})}}
async function makeProject(f){return f.store.projectCreate({name:'Delivery fixture',platform:'web'},undefined,f.policy)}
async function register(f,project,directory,extra={}){return f.service.execute({action:'source.register',projectId:project.id,expectedRevision:project.revision,directory,...extra},f.context)}
async function waitOutput(handle,expected){if(handle.observed.stdout.readFrom(0).text.includes(expected))return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{handle.events.removeListener('stdout',read);reject(Error('Expected process output was not produced'))},2000),read=()=>{if(handle.observed.stdout.readFrom(0).text.includes(expected)){clearTimeout(timer);handle.events.removeListener('stdout',read);resolve()}};handle.events.on('stdout',read);read()})}
function response(){return {status:0,headers:{},body:Buffer.alloc(0),writeHead(status,headers){this.status=status;this.headers=headers||{}},end(body){this.body=Buffer.isBuffer(body)?body:Buffer.from(body||'')}}}
function req(url,owner=false,remoteAddress='127.0.0.1',method='GET'){return {url:new URL(url,'http://local.invalid').pathname,method,headers:owner?{authorization:'owner'}:{},socket:{remoteAddress}}}
async function shareRequest(service,request,result){await service.handleShare(request,result);if(result.status===302)await service.handleShare(req(result.headers.Location,request.headers.authorization==='owner',request.socket.remoteAddress,request.method),result);return result}
function unzipStored(bytes){const entries=new Map();let cursor=0;while(bytes.readUInt32LE(cursor)===0x04034b50){assert.equal(bytes.readUInt16LE(cursor+8),0);const crc=bytes.readUInt32LE(cursor+14),size=bytes.readUInt32LE(cursor+18),length=bytes.readUInt16LE(cursor+26),extra=bytes.readUInt16LE(cursor+28),name=bytes.subarray(cursor+30,cursor+30+length).toString('utf8'),start=cursor+30+length+extra,content=bytes.subarray(start,start+size);assert.equal(crc32(content),crc);entries.set(name,content);cursor=start+size;}assert.equal(bytes.readUInt32LE(cursor),0x02014b50);assert.equal(bytes.readUInt32LE(bytes.length-22),0x06054b50);assert.equal(bytes.readUInt16LE(bytes.length-14),entries.size);return entries}
