async function designFixture(f){const project=await makeProject(f);const created=await f.store.artboardCreate({projectId:project.id,expectedRevision:project.revision,name:'Exported page',html:'<!doctype html><html><head><link rel="stylesheet" href="../assets/local/root.css"></head><body><button onclick="this.dataset.clicked=1">Interact</button><img src="../assets/local/pixel.png"><a href="https://example.com">External link</a></body></html>'},undefined,f.policy);const root=f.provider.processPath(await f.store.target(`projects/${project.id}`));await fs.mkdir(checked(f.root,path.join(root,'assets/local/nested')),{recursive:true});await fs.writeFile(checked(f.root,path.join(root,'assets/local/root.css')),'@import "nested/fonts.css";.image{background:url(/assets/local/pixel.png)}');await fs.writeFile(checked(f.root,path.join(root,'assets/local/nested/fonts.css')),'@font-face{font-family:Demo;src:url(../demo.woff2)}');await fs.writeFile(checked(f.root,path.join(root,'assets/local/demo.woff2')),font);await fs.writeFile(checked(f.root,path.join(root,'assets/local/pixel.png')),png);await fs.writeFile(checked(f.root,path.join(root,'requirements.md')),'PRIVATE REQUIREMENTS MUST NOT LEAK');await fs.mkdir(checked(f.root,path.join(root,'.workbench')));await fs.writeFile(checked(f.root,path.join(root,'.workbench/drafts.json')),'PRIVATE DRAFT CHAT AND TOKEN');return {project:created.project,page:created.artboard,root}}

test('stored ZIP uses valid CRC32, portable names, central directory and refuses traversal',()=>{assert.equal(crc32(Buffer.from('123456789')),0xcbf43926);const zip=zipStored([{path:'字体/demo.woff2',bytes:font},{path:'index.html',bytes:Buffer.from('<html>test</html>')}]);const entries=unzipStored(zip);assert.deepEqual(entries.get('字体/demo.woff2'),font);assert.throws(()=>zipStored([{path:'../outside',bytes:png}]),{code:'INVALID_PATH'});assert.throws(()=>zipStored([{path:'a',bytes:png},{path:'a',bytes:png}]),{code:'INVALID_ZIP_ENTRY'})});

test('deleted designs exclude their retained page metadata from current-version exports',()=>{const service=Object.create(DeliveryService.prototype),project={artboards:[{id:'a-retained',htmlPath:'html/retained.html',designId:'d-deleted'}],workbench:{designs:[{id:'d-deleted',pageIds:['a-retained'],deletedAt:'2026-01-01T00:00:00.000Z'}]}};assert.throws(()=>service.selectedPages(project,{}),{code:'EMPTY_EXPORT'});assert.throws(()=>service.selectedPages(project,{pageId:'a-retained'}),{code:'PAGE_NOT_FOUND'})});

test('source registration keeps an external root in place and never expands the current policy',()=>fixture(async f=>{const project=await makeProject(f),directory=checked(f.root,path.join(f.root,'external-source'));await fs.mkdir(directory);await fs.writeFile(path.join(directory,'original.txt'),'original');const registered=await register(f,project,directory);assert.equal(registered.source.directory,directory);assert.equal(registered.source.root,directory);assert.equal(registered.source.readonly,true);assert.equal(registered.source.writable,false);assert.equal(await fs.readFile(path.join(directory,'original.txt'),'utf8'),'original');assert.ok(f.provider.writes.every(w=>w.policy===f.policy));assert.equal(f.policy.additionalWritableRoots,undefined);await assert.rejects(f.service.execute({action:'source.register',projectId:project.id,expectedRevision:registered.projectRevision,directory}, {policy:f.policy,user:false}),{code:'USER_ONLY'});const updated=await f.service.execute({action:'source.update',projectId:project.id,sourceId:registered.source.id,expectedRevision:registered.projectRevision,writable:true,writablePaths:['src/App.js']},f.context);assert.equal(updated.source.writable,true);assert.deepEqual(updated.source.writablePaths,['src/App.js'])}));

test('real selected-path Git commit excludes unrelated staged changes and preserves their index entry',()=>fixture(async f=>{let project=await makeProject(f);const directory=checked(f.root,path.join(f.root,"source repo ' $()"));await fs.mkdir(directory);runGit(directory,'init','-b','main');runGit(directory,'config','user.name','Delivery Test');runGit(directory,'config','user.email','delivery@example.invalid');await fs.writeFile(path.join(directory,'chosen.txt'),'old chosen');await fs.writeFile(path.join(directory,'unrelated.txt'),'old unrelated');runGit(directory,'add','.');runGit(directory,'commit','-m','initial');const registration=await register(f,project,directory);project=registration.project;await fs.writeFile(path.join(directory,'chosen.txt'),'new chosen');await fs.writeFile(path.join(directory,'unrelated.txt'),'UNRELATED STAGED');runGit(directory,'add','--','unrelated.txt');const selected='new file;$(touch injection-marker).txt';await fs.writeFile(path.join(directory,selected),'selected new binary-safe text');const before=runGit(directory,'show',':unrelated.txt');const status=await f.service.execute({action:'git.status',projectId:project.id,sourceId:registration.source.id},{policy:f.policy});assert.ok(status.files.some(file=>file.path==='unrelated.txt'&&file.index==='M'));await assert.rejects(f.service.execute({action:'git.commit',projectId:project.id,sourceId:registration.source.id,paths:['chosen.txt'],message:'blocked'},{policy:f.policy}),{code:'USER_ONLY'});const committed=await f.service.execute({action:'git.commit',projectId:project.id,sourceId:registration.source.id,paths:['chosen.txt',selected],message:'only selected files',expectedHead:status.head},f.context);assert.equal(committed.success,true);assert.deepEqual(new Set(runGit(directory,'diff-tree','--no-commit-id','--name-only','-r','HEAD').split('\n')),new Set(['chosen.txt',selected]));assert.equal(runGit(directory,'show','HEAD:unrelated.txt'),'old unrelated');assert.equal(runGit(directory,'show',':unrelated.txt'),before);assert.ok(runGit(directory,'diff','--cached','--name-only').includes('unrelated.txt'));await assert.rejects(fs.stat(path.join(directory,'injection-marker')),{code:'ENOENT'});assert.ok(f.shell.requests.every(request=>request.sandboxPolicy===f.policy));assert.ok(f.shell.requests.every(request=>!request.command.includes(selected)));await assert.rejects(f.service.execute({action:'git.commit',projectId:project.id,sourceId:registration.source.id,paths:['..'],message:'bad'},f.context),{code:'INVALID_PATH'})}));

test('Git branch changes block unsaved drafts and actual dirty state, then report the switched branch',()=>fixture(async f=>{const project=await makeProject(f),directory=checked(f.root,path.join(f.root,'git-source'));await fs.mkdir(directory);runGit(directory,'init','-b','main');runGit(directory,'config','user.name','Delivery Test');runGit(directory,'config','user.email','delivery@example.invalid');await fs.writeFile(path.join(directory,'file.txt'),'clean');runGit(directory,'add','.');runGit(directory,'commit','-m','initial');runGit(directory,'branch','other');const registered=await register(f,project,directory);f.owner.workbench.hasUnsavedDrafts=async()=>({dirty:true,resources:[{resourceId:'draft-page'}]});await assert.rejects(f.service.execute({action:'git.checkout',projectId:project.id,sourceId:registered.source.id,branch:'other'},f.context),error=>error.code==='UNSAVED_DRAFTS'&&error.details.resources[0].resourceId==='draft-page');assert.equal(runGit(directory,'branch','--show-current'),'main');f.owner.workbench.hasUnsavedDrafts=async()=>({dirty:false,resources:[]});await fs.writeFile(path.join(directory,'file.txt'),'dirty');await assert.rejects(f.service.execute({action:'git.checkout',projectId:project.id,sourceId:registered.source.id,branch:'other'},f.context),{code:'GIT_DIRTY'});await fs.writeFile(path.join(directory,'file.txt'),'clean');const switched=await f.service.execute({action:'git.checkout',projectId:project.id,sourceId:registered.source.id,branch:'other'},f.context);assert.equal(switched.success,true);assert.equal(switched.status.branch,'other');assert.equal(runGit(directory,'log','--oneline').split('\n').length,1)}));

test('source maps return real contained source locations; missing, escaped or stale mappings remain references',()=>fixture(async f=>{const project=await makeProject(f),directory=checked(f.root,path.join(f.root,'mapped-source'));await fs.mkdir(path.join(directory,'src'),{recursive:true});await fs.mkdir(path.join(directory,'dist'));const original='export const view = 1;';await fs.writeFile(path.join(directory,'src/App.js'),original);await fs.writeFile(path.join(directory,'dist/app.js'),'const view=1;\n//# sourceMappingURL=app.js.map');await fs.writeFile(path.join(directory,'dist/app.js.map'),JSON.stringify({version:3,file:'app.js',sources:['../src/App.js'],sourcesContent:[original],names:[],mappings:'AAAA'}));const registered=await register(f,project,directory);const query={action:'source.map',projectId:project.id,sourceId:registered.source.id,generatedFile:'dist/app.js',line:1,column:0};const mapped=await f.service.execute(query,{policy:f.policy});assert.equal(mapped.mode,'source');assert.equal(mapped.referenceOnly,false);assert.equal(mapped.path,'src/App.js');assert.equal(mapped.line,1);await fs.writeFile(path.join(directory,'src/App.js'),'edited after map');const stale=await f.service.execute(query,{policy:f.policy});assert.equal(stale.referenceOnly,true);assert.equal(stale.reason,'SOURCE_MAP_CONTENT_STALE');const absent=await f.service.execute({...query,generatedFile:'no.js'},{policy:f.policy});assert.equal(absent.referenceOnly,true);const escaped=await f.service.execute({...query,mapPath:'../outside.map'},{policy:f.policy});assert.equal(escaped.referenceOnly,true)}));

test('source commands remain alive across status and are stopped and awaited on explicit stop, caller abort and owner disposal',()=>fixture(async f=>{const project=await makeProject(f),directory=checked(f.root,path.join(f.root,'running-source'));await fs.mkdir(directory);const registered=await register(f,project,directory,{command:'exec node -e "console.log(\'ready Bearer secret-token\');setInterval(()=>{},1000)"',port:32123});const input={projectId:project.id,sourceId:registered.source.id};await assert.rejects(f.service.execute({action:'source.start',...input},{policy:f.policy}),{code:'USER_ONLY'});const started=await f.service.execute({action:'source.start',...input},f.context);assert.equal(started.run.status,'running');const first=f.shell.executions.at(-1);await waitOutput(first,'ready');const logs=await f.service.execute({action:'source.logs',...input},{policy:f.policy});assert.ok(logs.stdout.text.includes('[redacted]'));assert.ok(!logs.stdout.text.includes('secret-token'));const status=await f.service.execute({action:'source.status',...input},{policy:f.policy});assert.equal(status.source.run.status,'running');assert.equal(f.shell.requests.at(-1).onExpiry,'none');await f.service.execute({action:'source.stop',...input},f.context);await first.done;assert.notEqual(first.status,'running');const controller=new AbortController();await f.service.execute({action:'source.start',...input},{...f.context,signal:controller.signal});const aborted=f.shell.executions.at(-1);controller.abort();await aborted.done;assert.notEqual(aborted.status,'running');await f.service.execute({action:'source.start',...input},f.context);const last=f.shell.executions.at(-1);await waitOutput(last,'ready');await f.service.dispose();assert.notEqual(last.status,'running');assert.equal(last.child.exitCode!==null||last.child.signalCode!==null,true)}));

test('portable ZIP contains final CSS, images, font bytes and runtime while excluding private documents and drafts',()=>fixture(async f=>{const design=await designFixture(f),result=await f.service.execute({action:'export.create',projectId:design.project.id,expectedRevision:design.project.revision,pageId:design.page.id,format:'design-package'},f.context);const artifact=await fs.readFile(path.join(design.root,result.export.artifactPath));assert.equal(sha(artifact),result.export.sha256);const entries=unzipStored(artifact);assert.deepEqual(entries.get('assets/local/demo.woff2'),font);assert.deepEqual(entries.get('assets/local/pixel.png'),png);assert.ok(entries.has('assets/local/nested/fonts.css'));assert.ok(entries.get(design.page.htmlPath).toString().includes('data-dsh-runtime'));assert.ok(entries.get('assets/local/root.css').toString().includes('url("pixel.png")'));assert.ok(entries.has('design-package.json'));assert.ok(![...entries.keys()].some(name=>/requirements|draft|\.workbench|context|project\.json/.test(name)));const all=Buffer.concat([...entries.values()]).toString();assert.ok(!all.includes('PRIVATE REQUIREMENTS'));assert.ok(!all.includes('PRIVATE DRAFT'));for(const file of result.manifest.files){assert.equal(hashEntry(entries,file.path),file.sha256);assert.equal((await fs.readFile(path.join(design.root,file.storedPath))).length,file.byteLength)}const download=response();await f.service.handleArtifact(req(result.export.downloadUrl,true),download);assert.equal(download.status,200);assert.deepEqual(download.body,artifact);const denied=response();await f.service.handleArtifact(req(result.export.downloadUrl),denied);assert.equal(denied.status,401);const badImage=f.service.execute({action:'export.create',projectId:design.project.id,expectedRevision:result.projectRevision,pageId:design.page.id,format:'png'},f.context);await assert.rejects(badImage,{code:'CAPTURE_UNAVAILABLE'})}));
function hashEntry(entries,name){assert.ok(entries.has(name),name);return sha(entries.get(name))}

test('image export passes frozen resources, region and background/editor flags to the image adapter boundary',()=>fixture(async f=>{const design=await designFixture(f);let captured;f.owner.imageCapture=async args=>{captured=args;return {mimeType:'image/png',bytesBase64:png.toString('base64'),metadata:{scope:'selection',nodeIds:['n-clip'],boundsVersion:{pageRevision:design.page.revision,sourceHash:design.page.contentHash,viewport:{width:320,height:200,authorization:'must-not-persist'},scene:'scene-preview',capability:'must-not-persist'},savedSourceHash:design.page.contentHash,sourceVersion:{pageRevision:design.page.revision,sourceHash:design.page.contentHash,authorization:'must-not-persist'},runtime:{present:true,scene:'scene-preview',authorization:'must-not-persist'},capability:'must-not-persist'}}};const result=await f.service.execute({action:'export.create',projectId:design.project.id,expectedRevision:design.project.revision,pageId:design.page.id,format:'png',region:{x:5,y:6,width:80,height:90},background:false,editorMarks:true,nodeIds:['n-clip'],sceneId:'scene-preview',quality:0,fullPage:false},f.context);assert.equal(captured.background,false);assert.equal(captured.editorMarks,true);assert.deepEqual(captured.region,{x:5,y:6,width:80,height:90});assert.deepEqual(captured.nodeIds,['n-clip']);assert.equal(captured.scene,'scene-preview');assert.equal(captured.sceneId,'scene-preview');assert.equal(captured.quality,0);assert.equal(captured.fullPage,false);assert.equal(captured.expectedRevision,design.project.revision);assert.equal(captured.expectedArtboardRevision,design.page.revision);assert.equal(result.manifest.capture.metadata.scope,'selection');assert.equal(result.manifest.capture.metadata.savedSourceHash,design.page.contentHash);assert.deepEqual(result.manifest.capture.metadata.boundsVersion,{pageRevision:design.page.revision,sourceHash:design.page.contentHash,scene:'scene-preview',viewport:{width:320,height:200}});assert.deepEqual(result.manifest.capture.metadata.sourceVersion,{pageRevision:design.page.revision,sourceHash:design.page.contentHash});assert.deepEqual(result.manifest.capture.metadata.runtime,{present:true,scene:'scene-preview'});assert.equal(result.manifest.capture.metadata.capability,undefined);assert.ok(captured.files.some(file=>file.path.endsWith('.woff2')));assert.equal(captured.policy,f.policy);assert.deepEqual(await fs.readFile(path.join(design.root,result.export.artifactPath)),png);assert.equal(result.export.mimeType,'image/png')}));

test('local shares require explicit user scope, freeze versions, enforce allowlists, owner/local access and immediate revocation',()=>fixture(async f=>{const design=await designFixture(f);await assert.rejects(f.service.execute({action:'share.create',projectId:design.project.id,expectedRevision:design.project.revision,scope:'unlisted'},{policy:f.policy}),{code:'USER_ONLY'});await assert.rejects(f.service.execute({action:'share.create',projectId:design.project.id,expectedRevision:design.project.revision,scope:'unlisted',hosting:'external'},f.context),{code:'PUBLISHER_NOT_CONFIGURED'});let shared=await f.service.execute({action:'share.create',projectId:design.project.id,expectedRevision:design.project.revision,pageId:design.page.id,scope:'unlisted',format:'design-package'},f.context);assert.equal(shared.share.hosting,'local');assert.match(shared.share.url,/^http:\/\/127\.0\.0\.1:53998\/api\/designer\/share\//);const before=response();await shareRequest(f.service,req(shared.share.url,false,'203.0.113.10'),before);assert.equal(before.status,200);assert.match(before.headers['Content-Security-Policy'],/sandbox allow-scripts/);assert.match(before.headers['Content-Security-Policy'],/connect-src 'none'/);assert.doesNotMatch(before.headers['Content-Security-Policy'],/allow-same-origin/);assert.equal(before.headers['Access-Control-Allow-Origin'],'*');assert.equal(before.headers['Referrer-Policy'],'no-referrer');const prefix=shared.share.url.replace(/\/$/,'');for(const forbidden of ['project.json','requirements.md','.workbench/drafts.json','design-package.json','context.json','../project.json']){const denied=response();await shareRequest(f.service,req(prefix+'/'+forbidden),denied);assert.equal(denied.status,404,forbidden)}const changed=await f.store.artboardCommit({projectId:design.project.id,artboardId:design.page.id,expectedRevision:shared.projectRevision,html:'<!doctype html><html><body><p>NEW DRAFT PAGE</p></body></html>'},undefined,f.policy);const frozen=response();await shareRequest(f.service,req(shared.share.url),frozen);assert.deepEqual(frozen.body,before.body,'later saved content cannot change the shared export');shared=await f.service.execute({action:'share.update',projectId:design.project.id,shareId:shared.share.id,expectedRevision:changed.projectRevision,expectedShareRevision:shared.share.revision,scope:'owner'},f.context);const ownerDenied=response();await shareRequest(f.service,req(shared.share.url),ownerDenied);assert.equal(ownerDenied.status,401);const ownerAllowed=response();await shareRequest(f.service,req(shared.share.url,true),ownerAllowed);assert.equal(ownerAllowed.status,200);shared=await f.service.execute({action:'share.update',projectId:design.project.id,shareId:shared.share.id,expectedRevision:shared.projectRevision,expectedShareRevision:shared.share.revision,scope:'local-link'},f.context);const remoteDenied=response();await shareRequest(f.service,req(shared.share.url,false,'203.0.113.10'),remoteDenied);assert.equal(remoteDenied.status,403);const localAllowed=response();await shareRequest(f.service,req(shared.share.url),localAllowed);assert.equal(localAllowed.status,200);const listed=await f.service.execute({action:'share.list',projectId:design.project.id},{policy:f.policy});assert.equal(listed.shares[0].url,undefined);assert.equal(listed.shares[0].capability,undefined);const revoked=await f.service.execute({action:'share.revoke',projectId:design.project.id,shareId:shared.share.id,expectedRevision:shared.projectRevision,expectedShareRevision:shared.share.revision},f.context);assert.ok(revoked.share.revokedAt);const unavailable=response();await shareRequest(f.service,req(shared.share.url,true),unavailable);assert.equal(unavailable.status,404)}));

test('actual document runtime and deep design-folder module/font/image dependencies remain portable',()=>fixture(async f=>{
  delete f.owner.documentExport;
  const project=await makeProject(f),created=await f.store.artboardCreate({projectId:project.id,expectedRevision:project.revision,name:'深层页面',html:'<!doctype html><html><body><button>实际运行时</button></body></html>'},undefined,f.policy),designId='d-deep',folder='designs/深层设计-d-deep',htmlPath=`${folder}/pages/home-${created.artboard.id}/index.html`;
  const original=`<!doctype html><html><head><link rel="stylesheet" href="../../styles/main.css"><script type="module" src="../../scripts/main.js"></script></head><body><button>实际运行时</button></body></html>`;
  await f.store.write(`projects/${project.id}/${htmlPath}`,original,null,undefined,f.policy);
  const next=await f.store.mutate(project.id,created.projectRevision,'Set deep design fixture',p=>{p.workbench={schemaVersion:1,designs:[{id:designId,name:'深层设计',folder,pageIds:[created.artboard.id],platform:'web',binding:{mode:'none'}}]};const page=p.artboards.find(p=>p.id===created.artboard.id);page.designId=designId;page.htmlPath=htmlPath;page.contentHash=sha(original)},undefined,f.policy,false);
  const root=f.provider.processPath(await f.store.target(`projects/${project.id}`)),full=path.join(root,folder);
  for(const dir of ['styles','scripts','assets/fonts','assets/images'])await fs.mkdir(checked(f.root,path.join(full,dir)),{recursive:true});
  await fs.writeFile(checked(f.root,path.join(full,'styles/main.css')),'@font-face{font-family:Deep;src:url(../assets/fonts/demo.woff2)} .logo{background:url(../assets/images/像素%20100%25.png)}');
  await fs.writeFile(checked(f.root,path.join(full,'scripts/main.js')),'import{message}from"./chunk.js";const icon=new URL("../assets/images/像素%20100%25.png",import.meta.url);console.log(message,icon);');
  await fs.writeFile(checked(f.root,path.join(full,'scripts/chunk.js')),'export const message="portable module";');
  await fs.writeFile(checked(f.root,path.join(full,'assets/fonts/demo.woff2')),font);await fs.writeFile(checked(f.root,path.join(full,'assets/images/像素 100%.png')),png);
  const result=await f.service.execute({action:'export.create',projectId:project.id,expectedRevision:next.revision,designId},f.context),entries=unzipStored(await fs.readFile(path.join(root,result.export.artifactPath)));
  assert.deepEqual(entries.get(`${folder}/assets/fonts/demo.woff2`),font);assert.deepEqual(entries.get(`${folder}/assets/images/像素 100%.png`),png);
  assert.ok(entries.has(`${folder}/scripts/chunk.js`));assert.ok(entries.get(`${folder}/scripts/main.js`).toString().includes('from"./chunk.js"'));
  const html=entries.get(htmlPath).toString();assert.ok(html.includes('dsh-document-runtime'));assert.ok(html.includes('dsh-document-model'));assert.ok(html.includes('"mode":"delivery"'));assert.ok(!html.includes('data-dsh-editor-overlay'));
  assert.equal(result.manifest.pages[0].htmlPath,htmlPath);assert.equal(result.manifest.pages[0].designId,designId);
}));

test('real configured local Git remote push/pull uses explicit user operations and never invents commits',()=>fixture(async f=>{
  const project=await makeProject(f),directory=checked(f.root,path.join(f.root,'push-source')),remote=checked(f.root,path.join(f.root,'remote.git')),other=checked(f.root,path.join(f.root,'other-source'));
  await fs.mkdir(directory);await fs.mkdir(remote);runGit(remote,'init','--bare');runGit(directory,'init','-b','main');runGit(directory,'config','user.name','Delivery Test');runGit(directory,'config','user.email','delivery@example.invalid');await fs.writeFile(path.join(directory,'file.txt'),'initial');runGit(directory,'add','.');runGit(directory,'commit','-m','initial');runGit(directory,'remote','add','origin',remote);
  const registered=await register(f,project,directory),input={projectId:project.id,sourceId:registered.source.id,remote:'origin',branch:'main'};
  await assert.rejects(f.service.execute({action:'git.push',...input},{policy:f.policy}),{code:'USER_ONLY'});
  const pushed=await f.service.execute({action:'git.push',...input},f.context);assert.equal(pushed.success,true);assert.equal(runGit(remote,'rev-parse','refs/heads/main'),runGit(directory,'rev-parse','HEAD'));
  runGit(f.root,'clone','--branch','main',remote,other);runGit(other,'config','user.name','Remote Test');runGit(other,'config','user.email','remote@example.invalid');await fs.writeFile(path.join(other,'file.txt'),'remote change');runGit(other,'add','.');runGit(other,'commit','-m','remote authored change');runGit(other,'push','origin','main');
  const pulled=await f.service.execute({action:'git.pull',...input},f.context);assert.equal(pulled.success,true);assert.equal(await fs.readFile(path.join(directory,'file.txt'),'utf8'),'remote change');assert.equal(runGit(directory,'rev-list','--count','HEAD'),'2');
  const created=await f.service.execute({action:'git.checkout',...input,branch:'user-created',create:true},f.context);assert.equal(created.success,true);assert.equal(created.status.branch,'user-created');assert.equal(runGit(directory,'rev-list','--count','HEAD'),'2');
  runGit(other,'switch','-c','topic');runGit(other,'push','origin','topic');runGit(directory,'fetch','origin');const tracked=await f.service.execute({action:'git.checkout',...input,branch:'origin/topic'},f.context);assert.equal(tracked.success,true);assert.equal(tracked.status.branch,'topic');assert.equal(runGit(directory,'rev-parse','--abbrev-ref','@{upstream}'),'origin/topic');assert.equal(runGit(directory,'rev-list','--count','HEAD'),'2');
}));

test('real existing Git conflicts are reported and never auto-committed or resolved',()=>fixture(async f=>{
  const project=await makeProject(f),directory=checked(f.root,path.join(f.root,'conflicted-source'));await fs.mkdir(directory);runGit(directory,'init','-b','main');runGit(directory,'config','user.name','Delivery Test');runGit(directory,'config','user.email','delivery@example.invalid');await fs.writeFile(path.join(directory,'file.txt'),'base\n');runGit(directory,'add','.');runGit(directory,'commit','-m','base');runGit(directory,'switch','-c','other');await fs.writeFile(path.join(directory,'file.txt'),'other\n');runGit(directory,'commit','-am','other change');runGit(directory,'switch','main');await fs.writeFile(path.join(directory,'file.txt'),'main\n');runGit(directory,'commit','-am','main change');const head=runGit(directory,'rev-parse','HEAD');const merge=spawnSync('git',['merge','other'],{cwd:directory,encoding:'utf8'});assert.equal(merge.status,1);
  const registered=await register(f,project,directory),status=await f.service.execute({action:'git.status',projectId:project.id,sourceId:registered.source.id},{policy:f.policy});assert.deepEqual(status.conflicts,['file.txt']);
  await assert.rejects(f.service.execute({action:'git.commit',projectId:project.id,sourceId:registered.source.id,paths:['file.txt'],message:'must not resolve'},f.context),error=>error.code==='GIT_CONFLICT'&&error.details.status.conflicts.includes('file.txt'));
  assert.equal(runGit(directory,'rev-parse','HEAD'),head);assert.ok((await fs.readFile(path.join(directory,'file.txt'),'utf8')).includes('<<<<<<<'));
}));

