  assert.match(anonymousPage.headers['Content-Security-Policy'],/script-src[^;]*'unsafe-hashes'/);const eventHash=createHash('sha256').update('this.dataset.clicked=1').digest('base64');assert.ok(anonymousPage.headers['Content-Security-Policy'].includes(`'sha256-${eventHash}'`));assert.doesNotMatch(anonymousPage.headers['Content-Security-Policy'],/script-src[^;]*'unsafe-inline'/);
