test('explicit share version update preserves its stable link and revocation persists across service instances',()=>fixture(async f=>{
  const design=await designFixture(f);let shared=await f.service.execute({action:'share.create',projectId:design.project.id,expectedRevision:design.project.revision,pageId:design.page.id,scope:'unlisted'},f.context);const stableURL=shared.share.url,changed=await f.store.artboardCommit({projectId:design.project.id,artboardId:design.page.id,expectedRevision:shared.projectRevision,html:'<!doctype html><html><body><p>EXPLICIT NEW VERSION</p></body></html>'},undefined,f.policy),exported=await f.service.execute({action:'export.create',projectId:design.project.id,expectedRevision:changed.projectRevision,pageId:design.page.id},f.context);
  shared=await f.service.execute({action:'share.update',projectId:design.project.id,shareId:shared.share.id,expectedRevision:exported.projectRevision,expectedShareRevision:shared.share.revision,exportId:exported.export.id},f.context);assert.equal(shared.share.url,stableURL);
  const restarted=new DeliveryService(f.owner);try{const page=response();await shareRequest(restarted,req(stableURL),page);assert.equal(page.status,200);assert.ok(page.body.toString().includes('EXPLICIT NEW VERSION'));await f.service.execute({action:'share.revoke',projectId:design.project.id,shareId:shared.share.id,expectedRevision:shared.projectRevision,expectedShareRevision:shared.share.revision},f.context);const revoked=response();await shareRequest(restarted,req(stableURL),revoked);assert.equal(revoked.status,404)}finally{await restarted.dispose()}
}));

