test('revocation during a snapshot read is checked again before publishing response bytes',()=>fixture(async f=>{
  const design=await designFixture(f),shared=await f.service.execute({action:'share.create',projectId:design.project.id,expectedRevision:design.project.revision,pageId:design.page.id,scope:'unlisted'},f.context);
  let notifyRead,releaseRead;const reading=new Promise(resolve=>{notifyRead=resolve}),release=new Promise(resolve=>{releaseRead=resolve}),originalRead=f.service.readProjectBytes.bind(f.service);
  f.service.readProjectBytes=async(...args)=>{const bytes=await originalRead(...args);notifyRead();await release;return bytes};
  const result=response(),pending=f.service.handleShare(req(new URL(shared.share.entryPath,shared.share.url).href),result);await reading;
  await f.service.execute({action:'share.revoke',projectId:design.project.id,shareId:shared.share.id,expectedRevision:shared.projectRevision,expectedShareRevision:shared.share.revision},f.context);releaseRead();await pending;assert.equal(result.status,404);assert.ok(!result.body.toString().includes('Interact'));
}));

